'amritsar-dalhousie-dharamshala' => array(
    'title' => 'Amritsar, Dalhousie and Dharamshala: a 6-day circuit',
    'cat' => 'India', 'group' => 'himachal',
    'desc' => 'Plan Amritsar, Dalhousie and Dharamshala together: Golden Temple and Wagah Border, Khajjiar, McLeod Ganj, and how many days to allow.',
    'lead' => 'This circuit pairs the Golden Temple and the Wagah Border ceremony with two of Himachal\'s quieter hill towns.',
    'sections' => array(
        array('Amritsar', '<p>Amritsar is for the Golden Temple (Harmandir Sahib), the langar, Jallianwala Bagh and the Beating Retreat ceremony at the Wagah Border in the late afternoon. Our itineraries start with Wagah on day 1 and the city on the way out.</p>'),
